from pysat.solvers import Glucose3
import itertools
from collections import defaultdict, deque

n = 23

# Edge variables
edge_to_var = {}
var_to_edge = {}
var_idx = 1
for i in range(n):
    for j in range(i+1, n):
        edge_to_var[(i,j)] = var_idx
        var_to_edge[var_idx] = (i,j)
        var_idx += 1

num_vars = var_idx - 1

solver = Glucose3()

# Degree constraints
for v in range(n):
    incident = []
    for u in range(v):
        incident.append(edge_to_var[(u,v)])
    for w in range(v+1, n):
        incident.append(edge_to_var[(v,w)])

    # At most 4: any 5 edges, at least one is false
    for combo in itertools.combinations(incident, 5):
        solver.add_clause([-c for c in combo])

    # At least 3: any (n-1)-3+1 = n-3 edges, at least one is true
    for combo in itertools.combinations(incident, n-3):
        solver.add_clause(list(combo))

def find_all_short_cycles_with_edges(edge_set, n, max_len=6):
    """Find all cycles of length 3 to max_len, returning the actual edges"""
    adj = defaultdict(set)
    for u, v in edge_set:
        adj[u].add(v)
        adj[v].add(u)

    found_cycles = set()  # Store as frozenset of edges to avoid duplicates

    for start in range(n):
        # BFS from start, tracking the path
        # State: (current_vertex, distance, path_as_list_of_edges)
        queue = deque()
        queue.append((start, 0, [], {start}))

        while queue:
            u, dist, path, visited = queue.popleft()

            if dist >= max_len:
                continue

            for v in sorted(adj[u]):
                edge = (min(u,v), max(u,v))
                if v == start and dist >= 2:
                    # Found a cycle back to start
                    cycle_edges = frozenset(path + [edge])
                    if len(cycle_edges) <= max_len:
                        found_cycles.add(cycle_edges)
                elif v not in visited:
                    new_visited = visited | {v}
                    queue.append((v, dist + 1, path + [edge], new_visited))

    return [list(c) for c in found_cycles]

# Iterative solving
iteration = 0
while True:
    iteration += 1
    if iteration > 200:
        print("Too many iterations")
        break

    if solver.solve():
        model = solver.get_model()
        edge_set = set()
        for lit in model:
            if lit > 0 and lit in var_to_edge:
                edge_set.add(var_to_edge[lit])

        # Check for short cycles
        short_cycles = find_all_short_cycles_with_edges(edge_set, n, 6)

        if not short_cycles:
            print(f"Found solution after {iteration} iterations!")
            print(f"Number of edges: {len(edge_set)}")

            # Verify
            adj = defaultdict(set)
            for u, v in edge_set:
                adj[u].add(v)
                adj[v].add(u)

            for v in range(n):
                deg = len(adj[v])
                if deg < 3 or deg > 4:
                    print(f"ERROR: vertex {v} has degree {deg}")

            # Verify girth
            def find_girth_bfs(adj, n):
                min_cycle = float('inf')
                for start in range(n):
                    dist = {start: 0}
                    parent = {start: -1}
                    queue = deque([start])
                    while queue:
                        u = queue.popleft()
                        for v in adj[u]:
                            if v not in dist:
                                dist[v] = dist[u] + 1
                                parent[v] = u
                                queue.append(v)
                            elif v != parent[u]:
                                cycle_len = dist[u] + dist[v] + 1
                                min_cycle = min(min_cycle, cycle_len)
                return min_cycle

            girth = find_girth_bfs(adj, n)
            print(f"Girth: {girth}")

            if girth >= 7:
                edge_list = sorted(edge_set)
                print("Edges:", edge_list)
                break
            else:
                print(f"Girth too small: {girth}")
                break
        else:
            print(f"Iteration {iteration}: Found {len(short_cycles)} short cycles")
            # Add constraints to break these cycles
            for cycle_edges in short_cycles:
                clause = [-edge_to_var[e] for e in cycle_edges]
                solver.add_clause(clause)
    else:
        print("UNSATISFIABLE")
        break
